-- {{APP_NAME}} — generated by `mre new`.
--
-- Everything here is Lua. Change it and save: `mre dev` pushes the new bundle
-- to the phone without rebuilding the APK.
--
-- Values declared with `mre.persist` keep their value across a hot reload.
-- Everything else starts fresh, which keeps reloads deterministic.

local count = mre.persist("count", 0)
local dark = mre.persist("dark", true)

local function card(title, body, background)
  return mre.column {
    padding = 18,
    radius = 18,
    background = background,
    mre.text { title, size = 21, weight = 700, color = "#F8FAFC" },
    mre.text { body, size = 14, color = "#94A3B8", margin = { top = 6 } },
  }
end

mre.app {
  view = function()
    return mre.column {
      padding = 24,
      gap = 14,
      background = "#0B1120",
      mre.text {
        "{{APP_NAME}}",
        size = 28,
        weight = 700,
        color = "#F8FAFC",
      },
      mre.text {
        "Edit src/main.lua and save — the phone updates instantly.",
        size = 14,
        color = "#94A3B8",
      },
      card("Signal", "Persisted count: " .. count(), "#152238"),
      mre.row {
        gap = 10,
        mre.button {
          "Increment",
          on_click = function() count(count() + 1) end,
        },
        mre.button {
          dark() and "Theme: dark" or "Theme: light",
          on_click = function()
            dark(not dark())
            mre.set_theme(dark() and "dark" or "light")
          end,
        },
      },
      mre.textfield {
        placeholder = "Type something…",
        value = "",
      },
    }
  },
}
